document.addEventListener("click",e=>{const t=e.target.closest(".js-debug-telemetry-toggle");if(!t)return;const n=t.getAttribute("data-level")||"none";t.disabled=!0;const o=window.CRM?.root||"";fetch(`${o}/api/system/telemetry-consent`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({level:n})}).then(()=>{window.location.reload()}).catch(()=>{t.disabled=!1})});